#[derive(Clone)]
struct Campaign {
    code: String,
    percent: u32,
    limits: Vec<String>,
}

let template = Campaign { code: "BF24".into(), percent: 20, limits: vec![] };
let mut mine = template.clone();      // field-wise copy
mine.limits.push("eu".into());       // template.limits untouched

